uint16_t get_tapping_term(uint16_t keycode, keyrecord_t *record) {
  return keycode == LT(3, KC_ENTER) ? 175 : TAPPING_TERM; // Enter must be a crisp tap
}
bool get_permissive_hold(uint16_t keycode, keyrecord_t *record) {
  switch (keycode) {
    case LT(2, KC_SPACE):          // prose safety: a lingering Space thumb must stay a space
    case MT(MOD_RSFT, KC_ESCAPE):  // Vim safety: Esc rolled into j must not become ⇧J
      return false;
    default:
      return true;                 // home-row mods (guarded by Chordal Hold + Flow Tap), Enter/NAV, Tab/NUM
  }
}
uint16_t get_quick_tap_term(uint16_t keycode, keyrecord_t *record) {
  switch (keycode) {
    case LT(2, KC_SPACE): case LT(3, KC_ENTER): case LT(1, KC_TAB): case MT(MOD_RSFT, KC_ESCAPE):
      return 0;                    // tap-then-hold on a thumb always means the layer or mod, never auto-repeat
    default:
      return QUICK_TAP_TERM;       // keeps tap-then-hold repeat on the home-row keys (kkkk in Vim)
  }
}

