// config.h
#define FLOW_TAP_TERM 150
// keymap.c
uint16_t get_flow_tap_term(uint16_t keycode, keyrecord_t *record, uint16_t prev_keycode) {
  switch (keycode) {
    case MT(MOD_LCTL, KC_A): case MT(MOD_LALT, KC_S): case MT(MOD_LGUI, KC_D):
    case MT(MOD_RGUI, KC_K): case MT(MOD_RALT, KC_L): case DUAL_FUNC_0:
      return is_flow_tap_key(prev_keycode) ? FLOW_TAP_TERM : 0;
    default:
      return 0; // never on thumbs
  }
}

