bool leader_add_user(uint16_t keycode) { return true; } // every sequence is one key: fire immediately
void leader_end_user(void) {
  if      (leader_sequence_one_key(KC_M)) SEND_STRING("&mut ");
  else if (leader_sequence_one_key(KC_S)) SEND_STRING("&mut self");
  else if (leader_sequence_one_key(KC_D)) SEND_STRING("#[derive(Debug, Clone)]");
  else if (leader_sequence_one_key(KC_T)) SEND_STRING("#[test]");
  else if (leader_sequence_one_key(KC_C)) SEND_STRING("#[cfg(test)]");
  else if (leader_sequence_one_key(KC_U)) SEND_STRING(".unwrap()");
  else if (leader_sequence_one_key(KC_E)) SEND_STRING(".expect(\"\")" SS_TAP(X_LEFT) SS_TAP(X_LEFT));
  else if (leader_sequence_one_key(KC_O)) SEND_STRING("Ok(())");
  else if (leader_sequence_one_key(KC_P)) SEND_STRING("println!(\"{:?}\", );" SS_TAP(X_LEFT) SS_TAP(X_LEFT));
}

